const payload = $input.first().json.body || $input.first().json;

const eventType = payload.eventType || 'STATUS_UPDATE';
const appointmentId = payload.appointmentId || 'N/A';
const status = payload.status || 'UPDATED';
const patientEmail = payload.patientEmail || 'paciente.sintetico@fcv.test';
const specialty = payload.specialtyName || 'Consulta Médica';
const reason = payload.reason ? `<p><strong>Motivo / Observación:</strong> ${payload.reason}</p>` : '';

let subject = `Notificación FCV: Cita #${appointmentId} - ${status}`;
let bannerColor = '#0284c7';
let statusMessage = `El estado de su cita médica ha cambiado a: <strong>${status}</strong>.`;

if (status === 'APPROVED') {
  bannerColor = '#16a34a';
  statusMessage = 'Su cita médica ha sido <strong>APROBADA</strong> exitosamente.';
} else if (status === 'REJECTED') {
  bannerColor = '#dc2626';
  statusMessage = 'Su solicitud de cita ha sido <strong>RECHAZADA</strong> por administración.';
} else if (status === 'CANCELLED') {
  bannerColor = '#d97706';
  statusMessage = 'Su cita médica ha sido <strong>CANCELADA</strong> y el horario ha sido liberado.';
}

const html = `
  <div style="font-family: Arial, sans-serif; color: #1e293b; max-width: 600px; padding: 20px; border: 1px solid #e2e8f0; border-radius: 8px;">
    <div style="background-color: ${bannerColor}; color: white; padding: 12px; border-radius: 6px; font-weight: bold; font-size: 16px;">
      Fundación Cardiovascular de Colombia — FCV Citas
    </div>
    <p style="margin-top: 16px;">Estimado(a) paciente,</p>
    <p>${statusMessage}</p>
    <ul>
      <li><strong>Cita #:</strong> ${appointmentId}</li>
      <li><strong>Especialidad:</strong> ${specialty}</li>
      <li><strong>Fecha del Evento:</strong> ${new Date().toLocaleString()}</li>
    </ul>
    ${reason}
    <p style="color: #64748b; font-size: 12px; margin-top: 20px;">Mensaje sintético de laboratorio académico FCV.</p>
  </div>
`;

return [{
  json: {
    patientEmail,
    subject,
    html,
    eventId: payload.eventId || Date.now(),
    appointmentId,
    status
  }
}];
